mapper.select:
SELECT id, rule_code, rule_id, period_key, current_max, create_time, update_time
FROM sys_code_sequence
WHERE rule_id = #{ruleId}
  AND period_key = #{periodKey}
FOR UPDATE

mapper.update:
UPDATE sys_code_sequence
SET current_max = current_max + #{increment},
    update_time = NOW()
WHERE rule_id = #{ruleId}
  AND period_key = #{periodKey}
